import { expect, expectTypeOf, assertType } from "./test/expect-shim.mjs";
import { parse } from "./src/parse/index.js";
import { zhCN } from "./src/locale/zh-CN/index.js";
{
{
{
expect(parse("2022年10月27日", "yyyy年MMMdd日", new Date(), {
            locale: zhCN,
        })).toEqual(new Date(2022, 9 /* Oct */, 27));
        expect(parse("2022年十月27日", "yyyy年MMMMdd日", new Date(), {
            locale: zhCN,
        })).toEqual(new Date(2022, 9 /* Oct */, 27));
}
}
}

